def min_rolls_to_score(target):
    dice_faces = [2, 3, 4, 5, 6, 7]
    dp = [-1] * (target + 1)

    def helper(score):
        if score == 0:
            return 0
        if dp[score] != -1:
            return dp[score]

        min_rolls = float('inf')
        for face in dice_faces:
            if score >= face:
                min_rolls = min(min_rolls, helper(score - face))

        dp[score] = min_rolls + 1 if min_rolls != float('inf') else float('inf')
        return dp[score]

    return helper(target)

